INSERT INTO service_blocks (page_slug, kind, position, locale, icon, title, description, payload_json) VALUES ('thg-fulfill', 'section_copy', 2, 'en', NULL, '', 'No automated quotes. Describe your product and needs — the THG team designs the right operational flow and contacts you directly.', '{"key":"consult-intro"}');
