INSERT INTO service_blocks (page_slug, kind, position, locale, icon, title, description, payload_json) VALUES ('thg-fulfill', 'section_copy', 2, 'zh', NULL, '', '不提供自动报价。描述您的产品与需求——THG团队将设计合适的运营流程并直接联系您。', '{"key":"consult-intro"}');
